  let previousBodyOverflow='';
  function showCourseDialog(n,title){const dialog=n.querySelector('#sx-course-dialog');if(!dialog)return;dialog.querySelector('#sx-course-dialog-title').textContent=title;if(!dialog.open){previousBodyOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.querySelector('#sx-course-dialog-message')?.replaceChildren();dialog.showModal();}dialog.querySelector('#sx-course-dialog-close').focus();}
