    n.querySelector('#sx-course-new').onclick=()=>newCourse(n);n.querySelector('#sx-course-reload').onclick=load;n.querySelector('#sx-course-import').onclick=async e=>{const button=e.currentTarget;if(!confirm(tr('Add the six courses listed on procatalyst.qa as unpublished drafts? Prices, duration and delivery will stay blank until you confirm them.','هل تريد إضافة الدورات الست المدرجة في procatalyst.qa كمسودات غير منشورة؟ ستبقى الأسعار والمدة وطريقة التقديم فارغة حتى تحددها.')))return;button.disabled=true;try{const result=await api('/import-procatalyst','POST',{});const box=n.querySelector('#sx-course-message');box.innerHTML=`<div class="notice" role="status">${tr('Imported ','تم استيراد ')}${result.created.length}${tr(' draft courses. ',' دورة كمسودات. ')}${result.skipped.length?tr('Already present: ','موجودة مسبقًا: ')+esc(result.skipped.join(', ')):''}</div>`;await load();}catch(error){showError(n,error);}finally{button.disabled=false;}};
