      const form=n.querySelector('#sx-center-profile'),fileInput=n.querySelector('#sx-profile-logo-file'),drop=n.querySelector('#sx-profile-logo-drop'),img=n.querySelector('#sx-profile-logo'),empty=n.querySelector('#sx-profile-logo-empty'),status=n.querySelector('#sx-profile-status');let currentLogo=p.logoUrl||'',selectedLogo=null,clearLogo=false,previewObjectUrl='';
